async function permanentlyDeleteCustomer(customer:Rec){const entered=window.prompt(`Permanently delete ${customer.email}'s app records and app-created Google Sheet? This cannot be undone. Type the customer's email to confirm.`);if(entered?.trim().toLowerCase()!==String(customer.email).toLowerCase())return;setBusy(true);setError('');try{await api('admin',{method:'PATCH',body:JSON.stringify({sub:customer.sub,action:'purge-deletion',confirmEmail:customer.email})});setAdminData(await api('admin'));setNotice('Permanent deletion verified.')}catch(e:any){setError('Permanent deletion not confirmed: '+e.message);api('admin').then(setAdminData).catch(()=>{})}finally{setBusy(false)}}
