async function selfDelete(){if(!accountSub||selfTimer.current)return;const exact='DELETE '+accountSub;if(window.prompt('This blocks your app access and moves the account to Deleted accounts for up to 48 hours. The admin can restore it during that window or delete it permanently sooner. Type '+exact)!==exact)return;setSelfCountdown(5);setNotice('Access block starts in 5 seconds. Cancel now to keep your account active.');selfTimer.current=setTimeout(async()=>{selfTimer.current=null;setSelfCountdown(0);setBusy(true);setNotice('');try{await api('account',{method:'POST',body:JSON.stringify({confirm:exact})});setAuth(false);setNotice('Account access blocked. Records and Google Sheet retained for restoration; nothing has been permanently erased yet.')}catch(e:any){setError(e.message)}finally{setBusy(false)}},5000)}
