async function updatePhoto(file:File){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setError('Choose a JPEG, PNG or WebP photo.');return}if(file.size>5*1024*1024){setError('Choose a photo under 5 MB.');return}setPhotoBusy(true);setError('');try{const img=await createImageBitmap(file);const side=Math.min(img.width,img.height),canvas=document.createElement('canvas');canvas.width=canvas.height=256;canvas.getContext('2d')!.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,256,256);img.close();const photo=canvas.toDataURL('image/jpeg',.82);if(photo.length>350000)throw Error('Photo is too large after resizing');await api('profile',{method:'PATCH',body:JSON.stringify({photo})});setCustomPhoto(photo);setNotice('Profile photo saved to your Google Sheet.')}catch(e:any){setError(e.message||'Could not save photo')}finally{setPhotoBusy(false);if(photoInput.current)photoInput.current.value=''}}
