async function setStatus(kind:string,row:Rec){const next=row.status==='Active'?'Inactive':'Active';if(!window.confirm(`${next==='Inactive'?'Deactivate':'Activate'} ${kind==='students'?row.name:row.name}? Payment history will be kept.`))return;try{await api(kind,{method:'PATCH',body:JSON.stringify({id:row.id,status:next})});await refresh();setNotice(`${kind==='students'?'Student':'Batch'} marked ${next.toLowerCase()}.`)}catch(e:any){setError(e.message)}}
