async function openWhatsApp(){const f=fees.find(x=>x.id===draft.feeId),raw=String(f?.student?.mobile||'').replace(/[^0-9]/g,'');const digits=raw.length===10?'91'+raw:raw;if(!/^\d{11,15}$/.test(digits)){setError('Enter a valid international mobile number for the parent.');return}try{const link='https://wa.me/'+digits+'?text='+encodeURIComponent(reminder);if(link.length>1900){await navigator.clipboard.writeText(reminder);window.open('https://wa.me/'+digits,'_blank','noopener,noreferrer');setNotice('Reminder copied. Paste and review it in WhatsApp before sending.')}else{window.open(link,'_blank','noopener,noreferrer');setNotice('WhatsApp opened with a draft. Check the recipient and message before sending.')} setModal('')}catch{setError('Could not copy message. Use Copy message first.')}}
