async function receiptPdf(share=false){if(!receipt)return;const p=receipt.payment;try{const fontBytes=await (await fetch('/fonts/DejaVuSans.ttf')).arrayBuffer();const binary=Array.from(new Uint8Array(fontBytes),b=>String.fromCharCode(b)).join('');const doc=new jsPDF();doc.addFileToVFS('DejaVuSans.ttf',btoa(binary));doc.addFont('DejaVuSans.ttf','DejaVu','normal');doc.setFont('DejaVu');doc.setFontSize(18);doc.text(receipt.instituteName,20,25);doc.setFontSize(11);const lines=[`Receipt: ${receipt.number}`,`Student: ${p.student.name}`,`Student ID: ${p.student.studentId}`,`Fee month: ${p.fee.month}`,`Batch: ${p.fee.batch?.name||p.student.batch?.name||''}`,`Amount paid: ${money(p.amount)}`,`Payment date: ${date(p.paymentDate)}`,`Payment mode: ${p.mode}`,`Remaining amount: ${money(receipt.remainingAmount)}`];lines.forEach((line,i)=>doc.text(line,20,44+i*10));if(share&&navigator.canShare&&navigator.share){const file=new File([doc.output('blob')],receipt.number+'.pdf',{type:'application/pdf'});if(navigator.canShare({files:[file]})){await navigator.share({files:[file],title:'Payment receipt '+receipt.number});return}}doc.save(receipt.number+'.pdf');if(share)setNotice('Native sharing is unavailable here. Download the PDF and attach it in WhatsApp.')}catch{setError('Could not generate PDF. Try Print receipt instead.')}}
