function downloadCsv(m:string,paid:Rec[],costs:Rec[]){const rows=[['Kind','Date','Name or category','Amount INR'],...paid.map(p=>['Payment',date(p.paymentDate),p.student.name,(p.amount/100).toFixed(2)]),...costs.map(e=>['Expense',date(e.date),e.category,(e.amount/100).toFixed(2)])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');downloadFile('fee-report-'+m+'.csv',new Blob([csv],{type:'text/csv;charset=utf-8'}))}
